<?php
namespace App\Filament\Resources\SettingResource\Pages; use App\Filament\Resources\SettingResource; use Filament\Resources\Pages\EditRecord; class EditSetting extends EditRecord{protected static string $resource=SettingResource::class;protected function mutateFormDataBeforeSave(array $data):array{if($this->record->key==='backup_frequency_days')$data['value']=(string)min(2,max(1,(int)$data['value']));if($this->record->key==='backup_retention_count')$data['value']=(string)min(60,max(3,(int)$data['value']));if($this->record->key==='backup_time'&&!preg_match('/^\d{2}:\d{2}$/',(string)$data['value']))$data['value']='03:00';return $data;}}
